:root {
  --bg: #050e0c;
  --panel: rgba(7, 20, 17, 0.78);
  --panel-deep: rgba(4, 13, 11, 0.92);
  --line: rgba(184, 255, 213, 0.12);
  --line-strong: rgba(184, 255, 213, 0.22);
  --text: #edf7f1;
  --muted: #7e9c91;
  --faint: #547168;
  --lime: #c9ff66;
  --mint: #58f0c0;
  --cyan: #66e6ff;
  --coral: #ff916d;
  --amber: #ffcf72;
  --danger: #ff6f63;
  --radius: 18px;
  --mono: "JetBrains Mono", "SFMono-Regular", Consolas, monospace;
  --sans: "Space Grotesk", "Avenir Next", "Segoe UI", sans-serif;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  overscroll-behavior: none;
}

body {
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
}

button {
  font: inherit;
  color: inherit;
}

button:focus-visible {
  outline: 2px solid var(--lime);
  outline-offset: 3px;
}

::selection {
  background: rgba(201, 255, 102, 0.28);
}

#app {
  position: relative;
  width: 100vw;
  height: 100dvh;
  min-height: 580px;
  overflow: hidden;
  isolation: isolate;
}

.ambient-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  background:
    radial-gradient(ellipse 72% 68% at 52% 44%, rgba(17, 51, 42, 0.8) 0%, rgba(7, 21, 18, 0.45) 45%, transparent 72%),
    radial-gradient(ellipse at 82% 18%, rgba(44, 157, 131, 0.1), transparent 45%),
    linear-gradient(160deg, #071510 0%, #04110f 42%, #020807 100%);
}

.aurora {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  opacity: 0.55;
  pointer-events: none;
}

.aurora-a {
  width: 48vw;
  height: 48vw;
  left: 15%;
  top: -22%;
  background: radial-gradient(circle, rgba(103, 255, 188, 0.15), transparent 68%);
  animation: drift-a 24s ease-in-out infinite alternate;
}

.aurora-b {
  width: 52vw;
  height: 40vw;
  right: -12%;
  bottom: -20%;
  background: radial-gradient(circle, rgba(42, 127, 194, 0.13), transparent 68%);
  animation: drift-b 30s ease-in-out infinite alternate;
}

@keyframes drift-a {
  to { transform: translate(5vw, 5vh) scale(1.08); }
}

@keyframes drift-b {
  to { transform: translate(-4vw, -4vh) scale(1.12); }
}

.grid-floor {
  position: absolute;
  left: -10%;
  right: -10%;
  bottom: -8%;
  height: 52%;
  background-image:
    linear-gradient(rgba(109, 255, 207, 0.075) 1px, transparent 1px),
    linear-gradient(90deg, rgba(109, 255, 207, 0.075) 1px, transparent 1px);
  background-size: 62px 62px;
  transform: perspective(500px) rotateX(63deg);
  transform-origin: center bottom;
  mask-image: radial-gradient(ellipse at center bottom, black 0%, transparent 68%);
  opacity: 0.5;
}

.grain {
  position: absolute;
  inset: 0;
  opacity: 0.14;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.35'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
  pointer-events: none;
}

#scene {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: grab;
}

#scene:active {
  cursor: grabbing;
}

.vignette {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    radial-gradient(ellipse 80% 78% at 50% 50%, transparent 42%, rgba(1, 7, 6, 0.35) 82%, rgba(1, 5, 4, 0.75) 100%),
    linear-gradient(to bottom, rgba(2, 8, 7, 0.55), transparent 18%, transparent 78%, rgba(2, 8, 7, 0.5));
}

.screen-brackets {
  position: absolute;
  inset: 13px;
  z-index: 3;
  pointer-events: none;
  opacity: 0.35;
}

.screen-brackets i {
  position: absolute;
  width: 24px;
  height: 24px;
  border-color: rgba(168, 255, 216, 0.45);
  border-style: solid;
}

.screen-brackets i:nth-child(1) { top: 0; left: 0; border-width: 1px 0 0 1px; }
.screen-brackets i:nth-child(2) { top: 0; right: 0; border-width: 1px 1px 0 0; }
.screen-brackets i:nth-child(3) { bottom: 0; left: 0; border-width: 0 0 1px 1px; }
.screen-brackets i:nth-child(4) { bottom: 0; right: 0; border-width: 0 1px 1px 0; }

/* ---------- top bar ---------- */

.topbar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 12;
  height: 94px;
  padding: 22px 30px 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 28px;
  pointer-events: none;
  background: linear-gradient(to bottom, rgba(3, 10, 8, 0.82), rgba(3, 10, 8, 0.3) 58%, transparent);
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 260px;
  pointer-events: auto;
}

.brand-mark {
  width: 43px;
  height: 43px;
  display: grid;
  place-items: center;
  color: var(--lime);
  border: 1px solid rgba(201, 255, 102, 0.25);
  border-radius: 13px;
  background: linear-gradient(150deg, rgba(201, 255, 102, 0.13), rgba(88, 240, 192, 0.03));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.09), 0 0 30px rgba(201, 255, 102, 0.07);
}

.brand-mark svg {
  width: 28px;
  height: 28px;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.brand-copy h1 {
  margin: 0;
  font-size: 24px;
  line-height: 1;
  font-weight: 700;
  letter-spacing: 0.14em;
}

.brand-copy span {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
}

.build-tag {
  align-self: flex-start;
  margin: 2px 0 0 4px;
  padding: 4px 6px;
  border: 1px solid var(--line);
  border-radius: 5px;
  color: var(--faint);
  font: 8px/1 var(--mono);
  letter-spacing: 0.08em;
}

.top-stats {
  display: flex;
  gap: 0;
  margin-top: 5px;
  padding: 0 4px;
  pointer-events: auto;
}

.stat {
  min-width: 104px;
  padding: 2px 22px 4px;
  border-left: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.stat:first-child {
  border-left: 0;
}

.stat span {
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--faint);
}

.stat strong {
  font-family: var(--mono);
  font-size: 19px;
  line-height: 1;
  font-weight: 500;
  letter-spacing: -0.03em;
  color: #dff9ea;
  font-variant-numeric: tabular-nums;
}

.stat:first-child strong {
  color: var(--lime);
}

.top-actions {
  display: flex;
  gap: 9px;
  pointer-events: auto;
}

.icon-button,
.mini-icon,
.dock-icon {
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid var(--line);
  background: rgba(7, 20, 17, 0.62);
  color: #a9c8bb;
  border-radius: 11px;
  cursor: pointer;
  transition: color 160ms ease, border-color 160ms ease, background 160ms ease, transform 160ms ease;
  -webkit-tap-highlight-color: transparent;
}

.icon-button {
  width: 42px;
  height: 42px;
  backdrop-filter: blur(16px);
}

.icon-button svg {
  width: 20px;
  height: 20px;
}

.icon-button:hover,
.mini-icon:hover,
.dock-icon:hover {
  color: var(--lime);
  border-color: rgba(201, 255, 102, 0.3);
  background: rgba(22, 47, 38, 0.78);
}

.icon-button:active,
.mini-icon:active,
.dock-icon:active {
  transform: scale(0.94);
}

.sound-off,
#btn-sound.muted .sound-on {
  display: none;
}

#btn-sound.muted .sound-off {
  display: block;
}

/* ---------- glass + panels ---------- */

.panel,
.glass {
  background:
    linear-gradient(150deg, rgba(18, 39, 33, 0.8) 0%, rgba(7, 20, 17, 0.76) 52%, rgba(4, 14, 12, 0.86) 100%);
  border: 1px solid var(--line);
  box-shadow:
    0 26px 70px rgba(0, 0, 0, 0.34),
    inset 0 1px 0 rgba(232, 255, 243, 0.075),
    inset 0 -1px 0 rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(22px) saturate(128%);
  -webkit-backdrop-filter: blur(22px) saturate(128%);
}

.panel {
  position: absolute;
  z-index: 10;
  width: 310px;
  border-radius: var(--radius);
  padding: 18px;
}

.panel::before {
  content: "";
  position: absolute;
  top: 0;
  left: 36px;
  right: 36px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(201, 255, 102, 0.32), transparent);
  pointer-events: none;
}

.specimen-panel {
  left: 28px;
  top: 104px;
  animation: panel-in 700ms 80ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.ecology-panel {
  right: 28px;
  top: 104px;
  animation: panel-in 700ms 160ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes panel-in {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

.panel-heading,
.log-heading,
.chart-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.panel-heading > span:first-child,
.log-heading > span:first-child {
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.17em;
  text-transform: uppercase;
  color: #b8d5c8;
}

.live-badge {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--mint);
}

.live-badge i,
.pulse-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--mint);
  box-shadow: 0 0 10px var(--mint);
  animation: pulse 2.2s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.42; transform: scale(0.78); }
}

.panel-index {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  color: var(--faint);
}

.specimen-heading {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 18px;
}

.specimen-glyph {
  position: relative;
  flex: 0 0 45px;
  width: 45px;
  height: 45px;
  border-radius: 12px;
  border: 1px solid rgba(201, 255, 102, 0.2);
  background:
    radial-gradient(circle at 40% 32%, rgba(201, 255, 102, 0.2), transparent 50%),
    rgba(4, 14, 11, 0.7);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  overflow: hidden;
}

.specimen-glyph::after {
  content: "";
  position: absolute;
  left: 6px;
  right: 6px;
  bottom: 6px;
  height: 1px;
  background: rgba(201, 255, 102, 0.22);
}

.specimen-glyph span {
  width: 4px;
  height: 16px;
  border-radius: 4px;
  background: var(--specimen-color, var(--lime));
  opacity: 0.75;
  transform: skewX(-11deg);
}

.specimen-glyph span:nth-child(2) {
  height: 24px;
  opacity: 1;
}

.specimen-glyph span:nth-child(3) {
  height: 11px;
  opacity: 0.48;
}

.specimen-name-wrap {
  min-width: 0;
  flex: 1;
}

.eyebrow {
  display: block;
  font-family: var(--mono);
  font-size: 7px;
  line-height: 1.4;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--faint);
}

.specimen-name-wrap h2 {
  margin: 3px 0 1px;
  font-size: 21px;
  line-height: 1.05;
  letter-spacing: -0.025em;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.specimen-name-wrap p {
  margin: 0;
  font-family: var(--mono);
  font-size: 9px;
  font-style: italic;
  letter-spacing: 0.03em;
  color: var(--muted);
}

.mini-icon {
  flex: 0 0 30px;
  width: 30px;
  height: 30px;
  border-radius: 8px;
}

.mini-icon svg {
  width: 16px;
  height: 16px;
}

.specimen-tags {
  display: flex;
  gap: 6px;
  margin-top: 13px;
}

.specimen-tags span {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #a4c2b5;
  border: 1px solid rgba(164, 194, 181, 0.14);
  background: rgba(164, 194, 181, 0.045);
  padding: 5px 7px;
  border-radius: 5px;
}

.specimen-tags .tag-alive {
  color: var(--mint);
  border-color: rgba(88, 240, 192, 0.18);
  background: rgba(88, 240, 192, 0.06);
}

.fitness-block {
  display: flex;
  align-items: center;
  gap: 17px;
  margin: 16px 0 17px;
  padding: 12px 13px;
  border: 1px solid rgba(184, 255, 213, 0.08);
  border-radius: 13px;
  background: radial-gradient(ellipse at 20% 50%, rgba(88, 240, 192, 0.075), transparent 65%), rgba(0, 0, 0, 0.14);
}

.fitness-ring {
  --ring-color: var(--mint);
  position: relative;
  flex: 0 0 76px;
  width: 76px;
  height: 76px;
  border-radius: 50%;
  background: conic-gradient(var(--ring-color) 0deg, rgba(255, 255, 255, 0.07) 0deg);
  display: grid;
  place-items: center;
  transition: background 500ms ease;
}

.fitness-ring::before {
  content: "";
  position: absolute;
  inset: 5px;
  border-radius: 50%;
  background: #0b1b17;
  border: 1px solid rgba(255, 255, 255, 0.055);
  box-shadow: inset 0 0 18px rgba(0, 0, 0, 0.3);
}

.fitness-ring::after {
  content: "";
  position: absolute;
  inset: 1px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.055);
}

.fitness-ring div {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.fitness-ring strong {
  font: 500 23px/1 var(--mono);
  letter-spacing: -0.06em;
  color: #effff6;
  font-variant-numeric: tabular-nums;
}

.fitness-ring span {
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--muted);
  margin-top: 3px;
}

.fitness-breakdown {
  flex: 1;
  display: grid;
  gap: 7px;
}

.fitness-breakdown div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted);
}

.fitness-breakdown b {
  font-weight: 500;
  color: #c8e4d7;
  font-variant-numeric: tabular-nums;
}

.section-label {
  display: flex;
  justify-content: space-between;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(184, 255, 213, 0.08);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--faint);
}

.trait-list {
  display: flex;
  flex-direction: column;
  gap: 9px;
  padding: 11px 0 12px;
}

.trait {
  cursor: pointer;
  border-radius: 5px;
  outline: none;
  transition: opacity 150ms ease;
}

.trait:hover {
  opacity: 0.88;
}

.trait-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 10px;
  margin-bottom: 5px;
}

.trait-top > span:first-child {
  font-size: 10px;
  color: #afcabd;
  letter-spacing: 0.01em;
}

.trait-top > span:last-child {
  font-family: var(--mono);
  font-size: 8px;
  color: #739384;
  font-variant-numeric: tabular-nums;
}

.trait-top em {
  margin-left: 6px;
  font-style: normal;
  font-size: 6.5px;
  letter-spacing: 0.06em;
  color: #46675b;
}

.trait-track {
  position: relative;
  height: 3px;
  border-radius: 3px;
  background: rgba(191, 255, 220, 0.075);
  overflow: visible;
}

.trait-track::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: repeating-linear-gradient(90deg, transparent 0 calc(25% - 1px), rgba(4, 13, 11, 0.9) calc(25% - 1px) 25%);
  z-index: 3;
  pointer-events: none;
}

.trait-fill {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  border-radius: inherit;
  background: linear-gradient(90deg, rgba(88, 240, 192, 0.38), var(--specimen-color, var(--lime)));
  box-shadow: 0 0 9px color-mix(in srgb, var(--specimen-color, var(--lime)) 40%, transparent);
  transition: width 600ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.trait-optimum {
  position: absolute;
  top: -2px;
  width: 1px;
  height: 7px;
  background: rgba(255, 255, 255, 0.34);
  z-index: 2;
  transform: translateX(-0.5px);
}

.trait-optimum::after {
  content: "optimum";
  position: absolute;
  top: -8px;
  left: 3px;
  font: 5px/1 var(--mono);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: rgba(255, 255, 255, 0.25);
  opacity: 0;
  transition: opacity 160ms ease;
}

.trait:hover .trait-optimum::after {
  opacity: 1;
}

.mutagen-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-top: 12px;
  border-top: 1px solid rgba(184, 255, 213, 0.08);
}

.pips {
  display: flex;
  gap: 4px;
  margin-top: 5px;
}

.pips i {
  width: 15px;
  height: 6px;
  border-radius: 2px;
  background: rgba(201, 255, 102, 0.16);
  border: 1px solid rgba(201, 255, 102, 0.14);
}

.pips i.full {
  background: var(--lime);
  border-color: var(--lime);
  box-shadow: 0 0 8px rgba(201, 255, 102, 0.35);
}

.button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border: 0;
  border-radius: 10px;
  padding: 11px 14px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.015em;
  cursor: pointer;
  transition: transform 160ms ease, filter 160ms ease, background 160ms ease, border-color 160ms ease, opacity 160ms ease;
  -webkit-tap-highlight-color: transparent;
}

.button:active {
  transform: translateY(1px) scale(0.99);
}

.button svg {
  width: 16px;
  height: 16px;
}

.button-quiet {
  padding: 8px 10px;
  color: #c9e2d6;
  background: rgba(196, 239, 217, 0.07);
  border: 1px solid rgba(184, 255, 213, 0.12);
  font-size: 9px;
}

.button-quiet:hover {
  background: rgba(201, 255, 102, 0.1);
  border-color: rgba(201, 255, 102, 0.22);
  color: var(--lime);
}

.button-quiet:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

/* ---------- ecology ---------- */

.panel-intro {
  margin: 13px 0 16px;
  font-size: 11px;
  line-height: 1.55;
  color: var(--muted);
}

.env-block {
  margin-bottom: 14px;
}

.env-title {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 7px;
  font-size: 10px;
  color: #c1d8cd;
}

.env-title span:last-child {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--faint);
}

.segmented {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3px;
  padding: 3px;
  border: 1px solid rgba(184, 255, 213, 0.08);
  border-radius: 9px;
  background: rgba(0, 0, 0, 0.18);
}

.segmented button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 8px 2px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: #648377;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.035em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 160ms ease;
  -webkit-tap-highlight-color: transparent;
}

.segmented button:hover {
  color: #b7d4c6;
  background: rgba(255, 255, 255, 0.035);
}

.segmented button.active {
  color: #eaffdf;
  background: linear-gradient(145deg, rgba(201, 255, 102, 0.14), rgba(88, 240, 192, 0.06));
  border-color: rgba(201, 255, 102, 0.18);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.segmented i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.75;
}

.segmented .dot-cold { color: #67baff; }
.segmented .dot-mild { color: #b5df86; }
.segmented .dot-hot { color: #ff9d66; }
.segmented button.active i { background: var(--lime); opacity: 1; box-shadow: 0 0 6px currentColor; }

.outlook {
  display: flex;
  gap: 10px;
  margin: 17px 0 14px;
  padding: 11px;
  border: 1px solid rgba(184, 255, 213, 0.08);
  border-radius: 11px;
  background: linear-gradient(140deg, rgba(88, 240, 192, 0.055), rgba(0, 0, 0, 0.12));
}

.outlook-icon {
  flex: 0 0 27px;
  width: 27px;
  height: 27px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  color: var(--mint);
  background: rgba(88, 240, 192, 0.08);
  border: 1px solid rgba(88, 240, 192, 0.12);
}

.outlook-icon svg {
  width: 15px;
  height: 15px;
}

.outlook p {
  margin: 4px 0 0;
  font-size: 9.5px;
  line-height: 1.5;
  color: #94b2a5;
}

.button-primary {
  width: 100%;
  padding: 14px 16px;
  color: #07130e;
  background: linear-gradient(115deg, #d8ff77 0%, #a8f669 42%, #55e9b9 100%);
  box-shadow:
    0 9px 26px rgba(110, 242, 154, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.5);
  font-size: 11px;
  letter-spacing: 0.015em;
}

.button-primary::after {
  content: "";
  position: absolute;
  inset: 1px;
  border-radius: 9px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  pointer-events: none;
}

.button-primary:hover {
  filter: brightness(1.06) saturate(1.04);
  box-shadow: 0 11px 32px rgba(110, 242, 154, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.6);
}

.button-primary svg {
  margin-left: auto;
}

.footnote {
  margin: 10px 0 0;
  text-align: center;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.07em;
  color: #456359;
}

kbd {
  display: inline-block;
  padding: 1px 4px;
  border-radius: 3px;
  border: 1px solid rgba(184, 255, 213, 0.12);
  background: rgba(184, 255, 213, 0.06);
  color: #88a99b;
  font: 6.5px/1.5 var(--mono);
}

/* ---------- lower panels ---------- */

.log-panel {
  position: absolute;
  z-index: 9;
  left: 28px;
  bottom: 24px;
  width: 310px;
  border-radius: 14px;
  padding: 13px 15px 14px;
  animation: panel-in 700ms 300ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.log-heading {
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(184, 255, 213, 0.07);
}

.log-heading > span:first-child {
  font-size: 7px;
}

.log-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-top: 9px;
  max-height: 65px;
  overflow: hidden;
}

.log-entry {
  display: flex;
  gap: 8px;
  align-items: baseline;
  font-size: 8.5px;
  line-height: 1.35;
  color: #89a79a;
  animation: log-in 350ms ease both;
}

@keyframes log-in {
  from { opacity: 0; transform: translateY(-3px); }
}

.log-entry em {
  flex: 0 0 auto;
  font: 6px/1.4 var(--mono);
  font-style: normal;
  color: var(--faint);
}

.log-entry b {
  font-weight: 500;
  color: #b5cfc2;
}

.log-entry.accent b {
  color: var(--lime);
}

.chart-panel {
  position: absolute;
  z-index: 9;
  right: 28px;
  bottom: 24px;
  width: 310px;
  border-radius: 14px;
  padding: 13px 15px 10px;
  animation: panel-in 700ms 380ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.chart-heading {
  margin-bottom: 7px;
}

.chart-heading > div {
  display: flex;
  align-items: baseline;
  gap: 9px;
}

.chart-heading span,
.chart-scale {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--faint);
}

.chart-heading strong {
  font: 500 15px/1 var(--mono);
  color: var(--lime);
  font-variant-numeric: tabular-nums;
}

.chart-heading .delta {
  color: #65877a;
}

#fitness-chart {
  display: block;
  width: 100%;
  height: 61px;
}

.chart-scale {
  display: flex;
  justify-content: space-between;
  margin-top: 3px;
  font-size: 6px;
  color: #3e5c51;
}

/* ---------- control dock ---------- */

.control-dock {
  position: absolute;
  z-index: 11;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%);
  height: 64px;
  width: 536px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 10px;
  border: 1px solid rgba(184, 255, 213, 0.13);
  border-radius: 16px;
  background: linear-gradient(150deg, rgba(16, 37, 31, 0.9), rgba(5, 16, 13, 0.92));
  box-shadow: 0 20px 55px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(24px) saturate(135%);
  -webkit-backdrop-filter: blur(24px) saturate(135%);
  animation: dock-in 800ms 240ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes dock-in {
  from { opacity: 0; transform: translate(-50%, 14px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

.dock-pop {
  padding-left: 4px;
  min-width: 84px;
}

.pop-dots {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 6px;
}

.pop-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  border: 1px solid transparent;
  background: var(--dot-color, #7d9c8e);
  cursor: pointer;
  padding: 0;
  transition: transform 150ms ease, box-shadow 150ms ease;
  -webkit-tap-highlight-color: transparent;
}

.pop-dot:hover {
  transform: scale(1.25);
}

.pop-dot.active {
  box-shadow: 0 0 0 2px #0a1a15, 0 0 0 3px var(--lime), 0 0 10px rgba(201, 255, 102, 0.45);
}

.dock-divider {
  width: 1px;
  height: 34px;
  background: rgba(184, 255, 213, 0.09);
}

.auto-button {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 3px 6px 3px 3px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  cursor: pointer;
  text-align: left;
  -webkit-tap-highlight-color: transparent;
}

.auto-icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  color: #08130e;
  background: var(--lime);
  box-shadow: 0 0 0 4px rgba(201, 255, 102, 0.07), 0 0 20px rgba(201, 255, 102, 0.16);
  transition: background 160ms ease, box-shadow 160ms ease;
}

.auto-icon svg {
  width: 18px;
  height: 18px;
}

.auto-button .icon-play { display: none; }
.auto-button.paused .icon-play { display: block; }
.auto-button.paused .icon-pause { display: none; }
.auto-button.paused .auto-icon {
  color: #c7e2d5;
  background: rgba(201, 255, 102, 0.14);
  box-shadow: inset 0 0 0 1px rgba(201, 255, 102, 0.2);
}

.auto-button span:last-child {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.auto-button small {
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--faint);
}

.auto-button b {
  font-size: 9px;
  font-weight: 500;
  color: #cfe5d9;
}

.speed-group {
  display: flex;
  gap: 2px;
  padding: 3px;
  border-radius: 7px;
  background: rgba(0, 0, 0, 0.22);
  border: 1px solid rgba(184, 255, 213, 0.06);
}

.speed-group button {
  border: 0;
  padding: 6px 7px;
  border-radius: 5px;
  background: transparent;
  color: #5d7d70;
  font: 8px/1 var(--mono);
  cursor: pointer;
  transition: all 140ms ease;
}

.speed-group button:hover {
  color: #b7d4c6;
}

.speed-group button.active {
  color: #e7ffda;
  background: rgba(201, 255, 102, 0.12);
}

.dock-actions {
  margin-left: auto;
  display: flex;
  gap: 6px;
}

.dock-icon {
  width: 34px;
  height: 34px;
  border-radius: 8px;
}

.dock-icon svg {
  width: 16px;
  height: 16px;
}

.dock-icon.active {
  color: var(--lime);
  border-color: rgba(201, 255, 102, 0.3);
  background: rgba(201, 255, 102, 0.1);
}

.mobile-only {
  display: none !important;
}

/* ---------- misc overlays ---------- */

.scene-caption {
  position: absolute;
  left: 50%;
  bottom: 102px;
  transform: translateX(-50%);
  z-index: 8;
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(137, 177, 158, 0.5);
  pointer-events: none;
}

.caption-line {
  width: 18px;
  height: 1px;
  background: rgba(137, 177, 158, 0.34);
}

.toast {
  position: absolute;
  z-index: 30;
  left: 50%;
  top: 104px;
  transform: translate(-50%, -12px);
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px 15px 10px 10px;
  border-radius: 12px;
  border: 1px solid rgba(201, 255, 102, 0.2);
  background: rgba(8, 24, 19, 0.9);
  box-shadow: 0 16px 44px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(20px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 260ms ease, transform 260ms ease;
}

.toast.visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

.toast-mark {
  width: 27px;
  height: 27px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  color: var(--lime);
  background: rgba(201, 255, 102, 0.1);
  border: 1px solid rgba(201, 255, 102, 0.15);
  font-size: 13px;
}

.toast div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.toast strong {
  font-size: 10px;
  font-weight: 500;
  color: #e9f9f0;
}

.toast span:last-child {
  font-family: var(--mono);
  font-size: 7px;
  color: var(--muted);
}

.hint {
  position: absolute;
  z-index: 20;
  left: 50%;
  bottom: 106px;
  transform: translateX(-50%);
  width: 440px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 13px;
  border: 1px solid rgba(201, 255, 102, 0.17);
  border-radius: 13px;
  background: rgba(8, 23, 18, 0.92);
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(20px);
  animation: hint-in 600ms 1.2s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  transition: opacity 300ms ease, transform 300ms ease;
}

.hint.hidden {
  opacity: 0;
  transform: translate(-50%, 8px);
  pointer-events: none;
}

@keyframes hint-in {
  from { opacity: 0; transform: translate(-50%, 10px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

.hint-icon {
  flex: 0 0 27px;
  width: 27px;
  height: 27px;
  border-radius: 50%;
  border: 1px solid rgba(201, 255, 102, 0.28);
  color: var(--lime);
  display: grid;
  place-items: center;
  font: 11px/1 var(--mono);
}

.hint p {
  flex: 1;
  margin: 0;
  font-size: 9px;
  line-height: 1.5;
  color: #8ca99c;
}

.hint p strong {
  font-weight: 500;
  color: #d3e8dd;
}

.hint button {
  flex: 0 0 auto;
  border: 0;
  background: rgba(201, 255, 102, 0.1);
  color: var(--lime);
  border-radius: 7px;
  padding: 7px 9px;
  font-size: 8px;
  cursor: pointer;
}

/* ---------- modal ---------- */

.modal {
  position: absolute;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(2, 8, 7, 0.62);
  backdrop-filter: blur(9px);
  opacity: 0;
  visibility: hidden;
  transition: opacity 250ms ease, visibility 250ms ease;
}

.modal.open {
  opacity: 1;
  visibility: visible;
}

.modal-card {
  position: relative;
  width: min(760px, 100%);
  max-height: min(760px, calc(100dvh - 48px));
  overflow: auto;
  border: 1px solid rgba(184, 255, 213, 0.16);
  border-radius: 22px;
  padding: 34px;
  background:
    radial-gradient(ellipse at 90% 0%, rgba(88, 240, 192, 0.1), transparent 48%),
    linear-gradient(150deg, rgba(18, 42, 35, 0.98), rgba(5, 16, 13, 0.98));
