import "./style.css";

import * as THREE from "three";
import { World } from "./world.js";
import { CreatureSystem } from "./creature.js";
import { AudioEngine } from "./audio.js";
import {
  CLIMATE,
  FORAGE,
  PREDATION,
  TRAIT_ROWS,
  GENE_META,
  breedPopulation,
  conditionOf,
  describeChange,
  diversity,
